def close_dormant_accounts(repo: Repository, policy) -> int:
    closed = 0
    for account in repo.find(policy.dormancy_spec):
        account.close()
        closed += 1
    return closed

def persist(entity, mapper: DataMapper, uow) -> None:
    payload = mapper.update(entity) if entity.id else mapper.insert(entity)
    uow.enqueue_write(payload)

def eligible_accounts(repo, dormant: Specification, high_value: Specification):
    criterion = dormant.and_(high_value.not_())
    return [a for a in repo.find_all() if criterion.is_satisfied_by(a)]

