from typing import Protocol, TypeVar, Generic, Iterable

ID = TypeVar('ID')

class Aggregate(Protocol, Generic[ID]):
    @property
    def id(self) -> ID: ...
    @property
    def version(self) -> int: ...
    def pull_events(self) -> Iterable[object]: ...

primitives.consumption_example:
def handle(cmd, repo):
    aggr: Aggregate = repo.get(cmd.id)
    aggr.apply(cmd)
    repo.save(aggr)
    return list(aggr.pull_events())

