def needs_acl(m: ContextMap, upstream: str, downstream: str) -> bool:
    kind = m.relationship(upstream, downstream)
    return kind in {'Conformist', 'Anticorruption Layer', 'Customer-Supplier'}

def on_event(ev, view: MaterializedView):
    view.apply(ev)
    # periodic, gated full rebuild is callable when schema evolves
    return view.query({'ready_to_serve': True})

def relay_orders(cdc: ChangeDataCapture, producer, pos):
