from typing import Protocol, Mapping, Any

class DomainEvent(Protocol):
    @property
    def event_id(self) -> str: ...
    @property
    def aggregate_id(self) -> str: ...
    @property
    def occurred_at(self) -> str: ...
    @property
    def version(self) -> int: ...
    @property
    def payload(self) -> Mapping[str, Any]: ...

primitives.consumption_example:
def publish(bus, evt: DomainEvent):
    bus.publish(evt.aggregate_id, {
        'id': evt.event_id,
        'v': evt.version,
        'at': evt.occurred_at,
        'body': dict(evt.payload),
    })

def wire(bus, consumer: IdempotentConsumer):
    @bus.subscribe('orders.placed')
    def _on(msg):
        consumer.handle(msg)

def kick_off(saga: SagaOrchestrator, order_id: str, payload):
    saga.start(correlation_id=order_id, input=payload)
    state, done = saga.status(order_id)
    return state, list(done)

def replay(stream: EventStream, key: str, start: int, fn):
    end = stream.tail(key)
    for event in stream.read_from(key, start):
        fn(event)
    return end

def rebuild(store: EventSourcedStore, fold, aggregate_id: str):
    events = list(store.load(aggregate_id))
    state = None
    for e in events:
        state = fold(state, e)
    return state, len(events)
